begin;
alter function public.hlc_create_company(text,text) set schema private;
create function public.hlc_create_company(company_name text,display_name text) returns uuid language sql security invoker set search_path='' as $$select private.hlc_create_company(company_name,display_name)$$;
revoke execute on function public.hlc_create_company(text,text) from public,anon;
grant execute on function public.hlc_create_company(text,text) to authenticated;
alter function public.hlc_create_invite(text) set schema private;
create function public.hlc_create_invite(member_role text) returns uuid language sql security invoker set search_path='' as $$select private.hlc_create_invite(member_role)$$;
revoke execute on function public.hlc_create_invite(text) from public,anon;
grant execute on function public.hlc_create_invite(text) to authenticated;
alter function public.hlc_join(uuid,text) set schema private;
create function public.hlc_join(invite_token uuid,display_name text) returns void language sql security invoker set search_path='' as $$select private.hlc_join(invite_token,display_name)$$;
revoke execute on function public.hlc_join(uuid,text) from public,anon;
grant execute on function public.hlc_join(uuid,text) to authenticated;
alter function public.hlc_create_project(text,text) set schema private;
create function public.hlc_create_project(project_name text,project_location text) returns uuid language sql security invoker set search_path='' as $$select private.hlc_create_project(project_name,project_location)$$;
revoke execute on function public.hlc_create_project(text,text) from public,anon;
grant execute on function public.hlc_create_project(text,text) to authenticated;
alter function public.hlc_assign(uuid,uuid,boolean) set schema private;
create function public.hlc_assign(project uuid,member uuid,assigned boolean) returns void language sql security invoker set search_path='' as $$select private.hlc_assign(project,member,assigned)$$;
revoke execute on function public.hlc_assign(uuid,uuid,boolean) from public,anon;
grant execute on function public.hlc_assign(uuid,uuid,boolean) to authenticated;
alter function public.hlc_create_lift(uuid,text,text) set schema private;
create function public.hlc_create_lift(project uuid,lift_description text,crane_name text) returns uuid language sql security invoker set search_path='' as $$select private.hlc_create_lift(project,lift_description,crane_name)$$;
revoke execute on function public.hlc_create_lift(uuid,text,text) from public,anon;
grant execute on function public.hlc_create_lift(uuid,text,text) to authenticated;
alter function public.hlc_add_photo(uuid,text) set schema private;
create function public.hlc_add_photo(lift uuid,object_path text) returns void language sql security invoker set search_path='' as $$select private.hlc_add_photo(lift,object_path)$$;
revoke execute on function public.hlc_add_photo(uuid,text) from public,anon;
grant execute on function public.hlc_add_photo(uuid,text) to authenticated;
create policy invites_deny_direct on public.hlc_invites for all to authenticated using(false) with check(false);
commit;